<template>
  <main class="moonlit-page">
    <section class="salon-hero">
      <div>
        <p class="eyebrow">月下会客厅 · 关系探索报告</p>
        <h1>抽三张牌，<br /><em>读懂你靠近爱情的方式。</em></h1>
        <p class="hero-copy">一份从关系偏好、人格倾向与象征牌面出发的说明书。慢一点，把在意的事说清楚。</p>
        <div class="hero-tags"><span>六章报告</span><span>仅本人可见</span><span>最长保存 {{ status.retentionDays }} 天</span></div>
      </div>
      <div class="moon-orbit" aria-hidden="true"><span class="moon"></span><span class="orbit-dot dot-one"></span><span class="orbit-dot dot-two"></span></div>
    </section>

    <section v-if="!auth.isLoggedIn" class="trial-gate">
      <p class="eyebrow">PRIVATE BETA · ONE REPORT</p>
      <h2>带着邀请码进来</h2>
      <p>无需注册账号。每枚邀请码可生成一份完整报告，生成失败可重试；成功后可跨设备恢复查看。</p>
      <form @submit.prevent="redeemTrial"><input v-model.trim="trialCode" autocomplete="off" spellcheck="false" placeholder="MM-…" aria-label="婚恋内测邀请码" /><button class="button primary" :disabled="redeeming || !trialCode">{{ redeeming ? "正在验证…" : "进入会客厅" }}</button></form>
      <small>人格与牌面提供一种观察关系的视角，不是科学测量、诊断或确定性预言。</small>
    </section>

    <template v-else>
      <section v-if="error" class="notice error" role="alert">{{ error }}</section>
      <section v-if="loading" class="notice">正在点亮你的会客厅…</section>

      <template v-else>
        <section class="disclaimer" aria-label="使用说明"><strong>先说明一件事</strong><p>这是一次关系观察，不是给你下结论。牌面只提供象征，报告只讨论你主动分享的内容，不推断他人的想法、经历或命运。</p></section>

        <section v-if="activeTask" ref="taskCard" class="task-card" aria-live="polite">
          <div class="task-heading"><div><p class="eyebrow">{{ activeTask.reportVersion === relationshipVersion ? "月下会客厅 · 关系探索报告" : "历史婚恋报告" }}</p><h2>{{ stageText }}</h2></div><span class="task-id">#{{ activeTask.id?.slice(0, 8) }}</span></div>
          <div class="task-track"><span :style="{ width: taskProgress + '%' }" :class="{ done: activeTask.status === 'done', failed: activeTask.status === 'error' }"></span></div>
          <p>{{ taskMessage }}</p>
          <p v-if="pollError" class="poll-error" role="status">{{ pollError }}</p>
          <router-link v-if="activeTask.status === 'done' && activeTask.reportId" class="button primary" :to="`/matchmaking-report/${activeTask.reportId}`">打开报告 →</router-link>
        </section>

        <section v-if="!status.relationshipEnabled" class="closed-state">
          <span class="closed-mark">✦</span><h2>会客厅正在整理灯火</h2><p>关系探索报告尚未开放新建。已有报告仍可继续阅读；如果你是 root，可在后台打开入口。</p>
        </section>

        <section v-else class="exploration-shell" aria-labelledby="exploration-title">
          <header class="flow-header"><div><p class="eyebrow">NEW EXPLORATION · {{ step + 1 }} / {{ steps.length }}</p><h2 id="exploration-title">{{ steps[step].title }}</h2></div><span class="flow-note">{{ steps[step].hint }}</span></header>
          <nav class="step-nav" aria-label="探索步骤"><button v-for="(item, index) in steps" :key="item.key" type="button" :class="{ active: step === index, visited: index < step }" :aria-current="step === index ? 'step' : undefined" @click="goStep(index)"><span>{{ String(index + 1).padStart(2, '0') }}</span>{{ item.label }}</button></nav>

          <div v-if="step === 0" class="flow-panel intro-panel">
            <p class="lead">今晚想从哪里开始？选择一个最接近此刻的入口，不需要回答得完美。</p>
            <fieldset><legend>你现在处在怎样的关系阶段？</legend><div class="choice-grid"><button v-for="item in stageOptions" :key="item.value" type="button" :class="{ selected: form.relationshipStage === item.value }" @click="form.relationshipStage = item.value"><strong>{{ item.label }}</strong><small>{{ item.description }}</small></button></div></fieldset>
            <fieldset><legend>这一次最想带走什么？</legend><div class="choice-grid intent-grid"><button v-for="item in intentOptions" :key="item.value" type="button" :class="{ selected: form.explorationIntent === item.value }" @click="form.explorationIntent = item.value"><strong>{{ item.label }}</strong><small>{{ item.description }}</small></button></div></fieldset>
          </div>

          <div v-else-if="step === 1" class="flow-panel personality-panel">
            <fieldset><legend>你想怎样进入“关系人格倾向”？</legend><div class="mode-grid"><button v-for="item in personalityModes" :key="item.value" type="button" :class="{ selected: form.personalityMode === item.value }" @click="selectPersonalityMode(item.value)"><strong>{{ item.label }}</strong><small>{{ item.description }}</small></button></div></fieldset>
            <div v-if="form.personalityMode === 'selfReported'" class="type-picker"><label>选择一个你熟悉的四字母入口<select v-model="form.declaredType" aria-label="选择四字母人格类型"><option value="">请选择</option><option v-for="type in catalogue.declaredTypes" :key="type">{{ type }}</option></select></label><small>这是你的自我描述入口，不代表本站替你测量或判断。</small></div>
            <div v-else-if="form.personalityMode === 'questionnaire'" class="questionnaire-block"><p class="question-progress">第 {{ personalityPage + 1 }} 组 · 每题选择更接近的一端</p><article v-for="question in visiblePersonalityQuestions" :key="question.id" class="bipolar-question"><p>{{ question.prompt }}</p><div class="bipolar-options"><label v-for="option in question.options" :key="option.value" :class="{ selected: form.personalityAnswers[question.id] === option.value }"><input v-model.number="form.personalityAnswers[question.id]" type="radio" :name="question.id" :value="option.value" /><span>{{ option.label }}</span></label></div></article><div class="question-actions"><button v-if="personalityPage" type="button" class="button quiet" @click="personalityPage--">上一组</button><button v-if="personalityPage < personalityPageCount - 1" type="button" class="button secondary" @click="personalityPage++">下一组</button></div></div>
            <p v-else class="skip-copy">你可以跳过人格入口。我们仍会从五个关系偏好和你的自述里寻找可用的线索。</p>
          </div>

          <div v-else-if="step === 2" class="flow-panel preferences-panel"><p class="lead">每道题都没有更好的答案。轨道上的位置只记录“这一次你更倾向于什么”。</p><article v-for="question in catalogue.relationshipQuestions" :key="question.id" class="preference-question"><div class="preference-head"><strong>{{ question.name }}</strong><span>{{ preferenceLabel(question) }}</span></div><div class="range-labels"><span>{{ question.left }}</span><span>{{ question.right }}</span></div><div class="range-options"><label v-for="value in question.values" :key="value" :class="{ selected: form.relationshipAnswers[question.id] === value }"><input v-model.number="form.relationshipAnswers[question.id]" type="radio" :name="question.id" :value="value" /><span>{{ value === 0 ? "都可能" : value < 0 ? "←" : "→" }}</span></label></div></article></div>

          <div v-else-if="step === 3" class="flow-panel optional-panel"><p class="lead">这些内容全部可选。少填一点，不会被解释成“缺少什么”。</p><label class="full-field">给今晚留一句话<textarea v-model.trim="form.personalNote" maxlength="200" rows="3" placeholder="可以写此刻想观察的事，不要填写联系方式或第三方身份信息。" /></label><div class="optional-grid"><label>城市（可选）<input v-model.trim="form.lifeContext.city" maxlength="40" placeholder="例如：杭州" /></label><label>工作节奏（可选）<input v-model.trim="form.lifeContext.workRhythm" maxlength="80" placeholder="例如：平日忙，周末较松" /></label><label>家庭居住期待（可选）<input v-model.trim="form.lifeContext.livingExpectation" maxlength="80" placeholder="例如：婚后希望独立居住" /></label></div><div class="partner-box"><div><strong>伴侣偏好（可选）</strong><p>不填写也会生成文字章节；不会从人格入口推断性取向。</p></div><div class="optional-grid"><label>性别<select v-model="form.partnerPreferences.gender"><option value="">不指定</option><option>女</option><option>男</option></select></label><label>年龄段<select v-model="form.partnerPreferences.ageBand"><option value="">不指定</option><option>22-26岁</option><option>27-31岁</option><option>32-36岁</option><option>36岁以上</option></select></label><label>气质<select v-model="form.partnerPreferences.style"><option value="">不指定</option><option>温柔亲切</option><option>干练知性</option><option>阳光活力</option><option>沉稳安静</option></select></label><label>场景<select v-model="form.partnerPreferences.scene"><option value="">不指定</option><option>日常休闲</option><option>职业装</option><option>咖啡馆约会</option><option>户外自然</option></select></label></div></div><label class="image-toggle"><input v-model="form.includePartnerImage" type="checkbox" /> 生成一张虚构伴侣人像（+{{ status.imageMediumCredits }} 积分）</label></div>

          <div v-else-if="step === 4" class="flow-panel tarot-panel"><div class="tarot-intro"><div><p class="eyebrow">THREE CARDS · UPRIGHT ONLY</p><h3>让牌面成为今晚的三个问题</h3><p>服务器会固定牌序，抽牌不扣积分；返回或刷新后，未提交的牌阵仍会被保留 24 小时。</p></div><span class="deck-seal">MAJOR<br />22</span></div><div v-if="!draw" class="draw-empty"><div class="card-back large-back"><span>✦</span><small>点击抽牌</small></div><button type="button" class="button primary" :disabled="drawing" @click="drawCards">{{ drawing ? "正在洗牌…" : "抽三张牌" }}</button></div><div v-else><div class="tarot-cards"><button v-for="(card, index) in draw.cards" :key="card.cardId" type="button" class="tarot-card" :class="{ revealed: revealed[index] }" :aria-label="revealed[index] ? `${card.name}，点击查看牌面含义` : `揭示第${index + 1}张牌`" @click="revealCard(index)"><span v-if="!revealed[index]" class="card-back"><b>✦</b><small>{{ slotLabels[index] }}</small></span><span v-else class="card-face"><img :src="cardImage(card.cardId)" :alt="`${card.name}牌面`" loading="lazy" width="240" height="360" @error="markImageFailed(card.cardId)" /><strong>{{ card.name }}</strong><small>{{ card.keywordsZh?.join(' · ') }}</small></span></button></div><div class="tarot-details"><article v-for="item in revealedCards" :key="item.card.cardId"><span>{{ slotLabels[item.index] }}</span><strong>{{ item.card.name }}</strong><p>{{ item.card.relationshipMeaningZh }}</p></article></div><button v-if="revealedCount < 3" type="button" class="button quiet" @click="revealNext">揭示下一张</button></div></div>

          <div v-else class="flow-panel review-panel"><p class="eyebrow">ONE LAST LOOK</p><h3>把今晚的材料核对一遍</h3><div class="review-grid"><article><span>关系阶段</span><strong>{{ stageLabel }}</strong></article><article><span>人格入口</span><strong>{{ personalityLabel }}</strong></article><article><span>关系偏好</span><strong>已完成 5 / 5</strong></article><article><span>三张牌</span><strong>{{ draw?.cards?.map(card => card.name).join(' · ') || '尚未抽牌' }}</strong></article></div><label class="image-toggle"><input v-model="form.includePartnerImage" type="checkbox" /> 同时生成虚构伴侣人像（+{{ status.imageMediumCredits }} 积分）</label><div class="cost-box"><span>本次报告</span><strong>{{ auth.isMatchmakingTrial ? "内测免费" : `${status.creditCost + (form.includePartnerImage ? status.imageMediumCredits : 0)} 积分` }}</strong><small>抽牌本身不收费；正式提交后才会扣费。生成失败会按真实响应补偿。</small></div></div>

          <footer class="flow-footer"><button v-if="step > 0" type="button" class="button quiet" @click="step--">← 上一步</button><span></span><button v-if="step < steps.length - 1" type="button" class="button primary" @click="nextStep">{{ step === 4 && !draw ? "先抽牌" : "继续" }} →</button><button v-else type="button" class="button primary" :disabled="creating || taskRunning" @click="generate">{{ creating ? "正在提交…" : "正式提交探索" }}</button></footer>
        </section>

        <section class="reports-list"><header><div><p class="eyebrow">月下会客厅 · 档案</p><h2>{{ auth.isRoot ? "全站报告" : "历史报告" }}</h2></div><button v-if="!auth.isMatchmakingTrial" type="button" class="text-button" @click="deleteData">删除全部资料</button></header><p v-if="!reports.length" class="empty-copy">还没有报告。完成一次探索后，它会安静地留在这里。</p><div v-else class="report-rows"><button v-for="item in reports" :key="item.id" type="button" class="report-row" @click="openReport(item.id)"><span class="row-owner" v-if="auth.isRoot">{{ item.ownerLabel || "未知用户" }}</span><span class="row-title">{{ item.reportVersion === relationshipVersion ? (item.title || "月下会客厅 · 关系探索报告") : "历史定位报告" }}</span><span class="row-type">{{ item.reportVersion === relationshipVersion ? (item.personalityLabel || "关系人格") : `${item.total ?? "—"} 分` }}</span><span class="row-date">{{ formatDate(item.createdAt) }}</span><span>→</span></button></div></section>
      </template>
    </template>

    <NModal v-model:show="validationOpen" preset="dialog" title="再补一小步"><p>{{ validationMessage }}</p><template #action><NButton type="primary" @click="validationOpen = false">我来补上</NButton></template></NModal>
  </main>
</template>

<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from "vue";
import { NButton, NModal } from "naive-ui";
import { useRouter } from "vue-router";
import { createTaskPoller } from "@/utils/taskPoller";
import { useAuthStore } from "@/stores/auth";
import { trialWorkspaceState } from "@/utils/matchmakingTrial";
import {
  createMatchmakingReport, deleteMatchmakingData, getMatchmakingCatalogue, getMatchmakingReports,
  getMatchmakingStatus, getMatchmakingTask, getMatchmakingTasks, getCurrentMatchmakingTarot,
  drawMatchmakingTarot,
} from "@/api";

const relationshipVersion = "relationship-exploration-v1";
const auth = useAuthStore(); const router = useRouter();
const loading = ref(true), error = ref(""), creating = ref(false), drawing = ref(false), validationOpen = ref(false), validationMessage = ref("");
const step = ref(0), personalityPage = ref(0), activeTask = ref(null), reports = ref([]), draw = ref(null), revealed = ref([false, false, false]), trialCode = ref(""), redeeming = ref(false), pollError = ref("");
const failedImages = reactive({}); let disposed = false;
const catalogue = reactive({ relationshipQuestions: [], personalityQuestions: [], declaredTypes: [], titles: [] });
const status = reactive({ creditCost: 2, credits: 0, retentionDays: 30, imageMediumCredits: 4, relationshipEnabled: false });
const form = reactive({ relationshipStage: "", explorationIntent: "", personalityMode: "skip", declaredType: "", personalityAnswers: {}, relationshipAnswers: {}, personalNote: "", includePartnerImage: false, partnerPreferences: { gender: "", ageBand: "", style: "", scene: "" }, lifeContext: { city: "", workRhythm: "", livingExpectation: "" } });
const steps = [{ key: "start", label: "关系情境", title: "先从此刻开始", hint: "选择一个入口" }, { key: "personality", label: "人格倾向", title: "你如何靠近", hint: "可自填、可回答、可跳过" }, { key: "preferences", label: "关系偏好", title: "把在意的事放上轨道", hint: "五个没有标准答案的问题" }, { key: "optional", label: "生活底稿", title: "愿意的话，再多说一点", hint: "全部可选" }, { key: "tarot", label: "三张塔罗", title: "抽出今晚的三个问题", hint: "服务器固定牌序" }, { key: "review", label: "核对提交", title: "把材料交给今晚", hint: "提交后正式生成" }];
const stageOptions = [{ value: "single", label: "一个人，想更懂自己", description: "把注意力放回自己的靠近方式" }, { value: "gettingCloser", label: "正在靠近某个人", description: "看看心动和表达之间的距离" }, { value: "inRelationship", label: "已经在一段关系里", description: "把相处里的误会说得更清楚" }, { value: "reflecting", label: "回头整理一段经历", description: "从过去带走可选择的下一步" }];
const intentOptions = [{ value: "understandSelf", label: "理解自己", description: "看见自己的需要和节奏" }, { value: "communicateBetter", label: "沟通得更好", description: "带走可以直接使用的话" }, { value: "understandAttraction", label: "理解心动", description: "分辨吸引和长期舒服" }, { value: "nextStep", label: "找到下一步", description: "让行动小而具体" }];
const personalityModes = [{ value: "selfReported", label: "我知道自己的类型", description: "自填四字母，只作为你的入口" }, { value: "questionnaire", label: "我想回答 16 题", description: "本站新编自我观察题，非验证量表" }, { value: "skip", label: "先跳过人格", description: "关系题仍然足够开始探索" }];
const stageLabel = computed(() => stageOptions.find(item => item.value === form.relationshipStage)?.label || "尚未选择");
const personalityLabel = computed(() => form.personalityMode === "selfReported" ? (form.declaredType || "尚未选择") : form.personalityMode === "questionnaire" ? `16 题 · ${Object.keys(form.personalityAnswers).length}/16` : "跳过人格");
const visiblePersonalityQuestions = computed(() => catalogue.personalityQuestions.slice(personalityPage.value * 4, personalityPage.value * 4 + 4));
const personalityPageCount = computed(() => Math.max(1, Math.ceil(catalogue.personalityQuestions.length / 4)));
const slotLabels = ["此刻的你", "关系中的暗线", "下一步"];
const revealedCards = computed(() => (draw.value?.cards || []).map((card, index) => ({ card, index })).filter(item => revealed.value[item.index]));
const revealedCount = computed(() => revealed.value.filter(Boolean).length);
const trialWorkspace = computed(() => trialWorkspaceState(auth.user?.trialAccess || {}));
const stageText = computed(() => ({ queued: "正在等一盏灯亮起", scoring: activeTask.value?.reportVersion === relationshipVersion ? "正在整理关系线索" : "正在计算市场信号", writing: activeTask.value?.reportVersion === relationshipVersion ? "正在写下你的关系解读" : "Mimo 正在撰写报告", illustrating: "正在生成虚构伴侣人像", saving: "正在保存报告", done: "报告已生成", error: "生成没有完成" }[activeTask.value?.stage] || "正在准备…"));
const taskProgress = computed(() => ({ queued: 8, scoring: 25, writing: 58, illustrating: 82, saving: 94, done: 100, error: 100 }[activeTask.value?.stage] || 0));
const taskRunning = computed(() => ["queued", "running"].includes(activeTask.value?.status));
const taskMessage = computed(() => activeTask.value?.status === "error" ? (activeTask.value.error || "正在等待补偿结果，请稍后查看") : activeTask.value?.status === "done" ? "报告已保存；你可以随时回来阅读。" : "可以离开这里，服务器会继续完成这份报告。返回后会接着显示进度。");
const taskPoller = createTaskPoller({ fetchTask: getMatchmakingTask, onError: text => { pollError.value = text; }, onTask: async task => { activeTask.value = task; if (task.status === "done") await refreshAfterDone(); else if (task.status === "error" && !task.compensationPending) await refreshAfterDone(); } });
function startPolling() { if (!disposed && activeTask.value) taskPoller.start(activeTask.value.id); }
function stopPolling() { taskPoller.stop(); }
async function refreshAfterDone() { if (auth.isMatchmakingTrial && activeTask.value?.reportId) { await router.replace(`/matchmaking-report/${activeTask.value.reportId}`); return; } try { const [r, s] = await Promise.all([getMatchmakingReports(), getMatchmakingStatus()]); reports.value = r.data || []; Object.assign(status, s.data || {}); auth.updateCredits(status.credits); } catch { /* keep current state */ } }
async function loadWorkspace() { try { const [c, s, r, t, current] = await Promise.all([getMatchmakingCatalogue(), getMatchmakingStatus(), getMatchmakingReports(), getMatchmakingTasks(), getCurrentMatchmakingTarot()]); Object.assign(catalogue, c.data || {}); Object.assign(status, s.data || {}); reports.value = r.data || []; const task = (t.data || []).find(item => ["queued", "running"].includes(item.status) || item.compensationPending); if (task) { activeTask.value = task; startPolling(); } draw.value = current.data?.draw || null; if (draw.value) revealed.value = [false, false, false]; } catch (e) { error.value = e.message || "加载会客厅失败"; } finally { loading.value = false; } }
async function redeemTrial() { redeeming.value = true; error.value = ""; try { const user = await auth.redeemTrial(trialCode.value); const access = user?.trialAccess || {}; if (access.status === "COMPLETED" && access.reportId && access.reportAvailable !== false) return router.replace(`/matchmaking-report/${access.reportId}`); await loadWorkspace(); } catch (e) { error.value = e.message || "邀请码验证失败"; } finally { redeeming.value = false; } }
onMounted(async () => { if (!auth.isLoggedIn) { loading.value = false; return; } if (auth.isMatchmakingTrial && trialWorkspace.value === "completed") { loading.value = false; return; } await loadWorkspace(); });
onUnmounted(() => { disposed = true; stopPolling(); });
function selectPersonalityMode(mode) { form.personalityMode = mode; form.declaredType = ""; if (mode !== "questionnaire") form.personalityAnswers = {}; }
function goStep(index) { if (index <= step.value) step.value = index; }
function nextStep() { const missing = stepMissing(); if (missing) { validationMessage.value = missing; validationOpen.value = true; return; } if (step.value === 4 && !draw.value) return drawCards(); step.value = Math.min(steps.length - 1, step.value + 1); }
function stepMissing(index = step.value) { if (index === 0) return !form.relationshipStage ? "先选一个关系阶段。" : !form.explorationIntent ? "再选一个这次最想带走的方向。" : ""; if (index === 1) return form.personalityMode === "selfReported" && !form.declaredType ? "请选择一个四字母类型，或切换到其他人格路径。" : form.personalityMode === "questionnaire" && Object.keys(form.personalityAnswers).length !== 16 ? "16 题还没有全部完成。" : ""; if (index === 2) return Object.keys(form.relationshipAnswers).length !== 5 ? "五个关系偏好都需要给一个位置。" : ""; if (index === 4) return !draw.value ? "先抽出三张牌，再继续。" : ""; return ""; }
async function drawCards() { drawing.value = true; error.value = ""; try { const res = await drawMatchmakingTarot(); draw.value = res.data; revealed.value = [false, false, false]; } catch (e) { error.value = e.message || "抽牌失败，请稍后重试"; } finally { drawing.value = false; } }
function revealCard(index) { revealed.value = Array.from({ length: 3 }, (_, itemIndex) => itemIndex === index || Boolean(revealed.value[itemIndex])); }
function revealNext() { const index = revealed.value.findIndex(value => !value); if (index >= 0) revealCard(index); }
function preferenceLabel(question) { const value = form.relationshipAnswers[question.id]; return value == null ? "还没有选择" : value === 0 ? "两端都可能" : value < 0 ? question.left : question.right; }
function cardImage(id) { return failedImages[id] ? "" : `/tarot/${id}.webp`; }
